sn_aia_tool.script:
(function(inputs) {
    var outputs = {};
    var lookup = new x_snc_pab_ee_tkit.LendingCustomerLookup();
    var res = lookup.lookupByPhone(inputs.phone_number, outputs);
    if (res) {
        res.customer_type = res.customer_type || "";
        res.customer_name = res.customer_name || "";
        res.customer_sys_id = res.customer_sys_id || "";
        res.contact_sys_id = res.contact_sys_id || "";
        res.consumer_sys_id = res.consumer_sys_id || "";
        res.account_name = res.account_name || "";
        res.account_sys_id = res.account_sys_id || "";
        res.financial_accounts_count = res.financial_accounts ? res.financial_accounts.length : 0;
        res.open_cases_count = res.open_cases ? res.open_cases.length : 0;
        res.visible_tasks_count = res.visible_tasks ? res.visible_tasks.length : 0;
        return res;
    }
    return { success: false, message: "No customer found matching phone number" };
})(inputs);
